local config = {
  ui_story_31870401_1_dialog_content = "Ah, PlayerName, you're finally here.",
  ui_story_31870401_2_dialog_content = "Squawk has been worried sick ever since Jabber disappeared.",
  ui_story_31870401_3_dialog_content = "Squawk! More food for me!",
  ui_story_31870401_4_dialog_content = "I take it this starling's name is Squawk?",
  ui_story_31870401_5_dialog_content = "It doesn't seem particularly worried...",
  ui_story_31870401_6_dialog_content = "Oh, Squawk's just spouting nonsense again. Don't listen to it.",
  ui_story_31870401_7_dialog_content = "No, you're spouting nonsense! Squawk!",
  ui_story_31870401_8_dialog_content = "Quiet, you! Anyway, Jabber is my other starling, one who looks like Squawk.",
  ui_story_31870401_9_dialog_content = "So, have you seen it around?",
  ui_story_31870401_10_dialog_content = "I, uh... can't really seem to recall.",
  ui_story_31870401_11_dialog_content = "Maybe we can start by remembering where you lost it?",
  ui_story_31870401_12_dialog_content = "Where have you been and what have you been doing in the last two days?",
  ui_story_31870401_13_dialog_content = "Well, now that you mention it, I visited plenty of places in that time span.",
  ui_story_31870401_14_dialog_content = "I'm in the middle of traveling across all of Astra, collecting all kinds of gossip and strange tales...",
  ui_story_31870401_15_dialog_content = "And using them to finish the third chapter of the <color=#FFB400>\"Scroll of Divine Ascension.\"</color>",
  ui_story_31870401_16_dialog_content = "The \"Scroll of Divine Ascension\"? Sounds pretty complicated.",
  ui_story_31870401_17_dialog_content = "That's only natural, considering this mysterious work was given to me by an even more mysterious person.",
  ui_story_31870401_18_dialog_content = "The first chapter is comprised of <color=#FFB400>all manner of strange and ancient legends</color> from all over the world.",
  ui_story_31870401_19_dialog_content = "The second chapter is full of <color=#FFB400>mysterious writings and symbols</color>, all of which are utterly incomprehensible...",
  ui_story_31870401_20_dialog_content = "That sounds awesome! What about the third chapter?",
  ui_story_31870401_21_dialog_content = "The third chapter... is a collection of <color=#FFB400>strange stories and rumors</color> gathered by yours truly!",
  ui_story_31870401_22_dialog_content = "And I reserve all rights for the final explanation of its content.",
  ui_story_31870401_23_dialog_content = "(Somehow I feel this isn't doing justice to the scroll...)",
  ui_story_31870401_24_dialog_content = "Still, I'd like for you to read it for yourself. Seeing is believing, after all.",
  ui_story_31870401_25_dialog_content = "There's only a single line of text on each page for the third chapter, so feel free to take a look.",
  ui_story_31870401_26_dialog_content = "Alright, let's see...",
  ui_story_31870401_27_dialog_content = "<size=50>\"Secret preparations to replace the Grand Marshal are well underway\"?!</size>",
  ui_story_31870401_28_dialog_content = "This part means that a certain pink-haired Illumina Commander has been secretly imitating the Grand Marshal's handwriting, among other things.",
  ui_story_31870401_29_dialog_content = "And... <size=50>\"The secret affairs of the Northland royal court are exposed\"?!</size>",
  ui_story_31870401_30_dialog_content = "Ah, yes, this part. It just means that the queen of Northland is prone to sleep-talking, among other things.",
  ui_story_31870401_31_dialog_content = "... I've never heard about any of these things! And why are you making them sound so much more sensational than they really are?!",
  ui_story_31870401_32_dialog_content = "Anyway, you should be pretty familiar with Astra now that you've been to so many places, right?",
  ui_story_31870401_33_dialog_content = "My travels are merely part of my job. My familiarity with this land is nothing compared to yours, I'm sure.",
  ui_story_31870401_34_dialog_content = "In the last two days, I revisited <color=#FFB400>Twin Pavilions Bay</color>, the <color=#FFB400>Rediesel Desert</color>, and <color=#FFB400>Umbraton</color> to hear the latest gossip.",
  ui_story_31870401_35_dialog_content = "Are you familiar with any of these places?",
  ui_story_31870401_36_dialog_content = "I'm certain someone like you must have some sort of <color=#FFB400>special</color> bird-finding technique, yes?",
  ui_story_31870401_37_dialog_content = "How would I know? I wasn't with you when you...",
  ui_story_31870401_38_dialog_content = "Wait, I got it!",
  ui_story_31870401_39_option_content = "Use psychic abilities",
  ui_story_31870401_40_dialog_content = "I can use my powers to see your memories based on the contents of these three pages.",
  ui_story_31870401_41_dialog_content = "Maybe I'll be able to find some clues that will lead us to Jabber!",
  ui_story_31870401_42_option_content = "Reach out to the parties involved in the gossips",
  ui_story_31870401_43_dialog_content = "That won't do, I'm afraid. As a rumor-gathering traveler of the world, I always wash my hands of old matters when my business is done.",
  ui_story_31870401_44_dialog_content = "I'm already thankful enough that the parties involved haven't tried to hunt me down. How could I possibly reach out to them?",
  ui_story_31870401_45_dialog_content = "I see... Guess I'll just have to use my psychic powers, huh?",
  ui_story_31870401_46_dialog_content = "I knew you were the right person to call upon.",
  ui_story_31870401_47_dialog_content = "Now then, could you please start with my memories of Twin Pavilions Bay?",
  ui_story_31870401_48_dialog_content = "Alright, the part about Twin Pavilions Bay should be... <color=#FFB400>\"The suspicious tendencies of the Shadowind's captain?!\"</color>",
  ui_story_31870401_49_option_content = "Force Boost!",
  ui_story_31870401_50_dialog_content = "Hey, is it me or has Captain Yuebai been acting weird lately?",
  ui_story_31870401_51_dialog_content = "I know what you mean. She's been going off all by herself these last few days, and then checking her clothes every time she gets back to the airship.",
  ui_story_31870401_52_dialog_content = "She's probably making sure there's nothing stuck to her clothing. I learned a long time ago that Umbraton's full of good and bad folks...",
  ui_story_31870401_53_dialog_content = "Hey, do you think it's possible she's been bought off to be an informant for that gang boss?",
  ui_story_31870401_54_dialog_content = "Shh! Shh!",
  ui_story_31870401_55_dialog_content = "...",
  ui_story_31870401_56_dialog_content = "C-Captain Yuebai!!",
  ui_story_31870401_57_dialog_content = "Oh? Do I smell some juicy gossip?",
  ui_story_31870401_58_dialog_content = "Yuebai is leaving!",
  ui_story_31870401_59_dialog_content = "Follow her! Follow her!",
  ui_story_31870401_60_dialog_content = "I know, I know! Now keep it down!",
  ui_story_31870401_61_dialog_content = "<color=#e8d9bb>Twin Pavilions Bay</color>",
  ui_story_31870401_62_dialog_content = "...",
  ui_story_31870401_63_dialog_content = "She seems afraid of being noticed. What on earth could she be up to?",
  ui_story_31870401_64_dialog_content = "She's going into a store!",
  ui_story_31870401_65_dialog_content = "It's a tavern!",
  ui_story_31870401_66_dialog_content = "Is this one of those taverns used for clandestine meetings...?",
  ui_story_31870401_67_dialog_content = "Urgh?!",
  ui_story_31870401_68_dialog_content = "Eww, what an awful stench!",
  ui_story_31870401_69_dialog_content = "Come one, come all! Try our delicious <color=#FFB400>snail noodles</color>, our brand-new product straight from the east!",
  ui_story_31870401_70_dialog_content = "A tasty treat in spite of the smell, one bite will send you all the way back to Longzhou!",
  ui_story_31870401_71_dialog_content = "The usual, please.",
  ui_story_31870401_72_dialog_content = "Got it! One bowl of extra-spicy snail noodles with double the snails and no pickled bamboo shoots, coming right up! Come have a seat, friend!",
  ui_story_31870401_73_dialog_content = "Ahhh, there's just no forgetting the aromas of our land's cuisine.",
  ui_story_31870401_74_dialog_content = "(So Yuebai's secret is that she likes sneaking out to eat snail noodles...)",
  ui_story_31870401_75_dialog_content = "(Wait, what am I doing? I'm supposed to be looking for Jabber!)",
  ui_story_31870401_76_dialog_content = "Still, Jabber was with you in this memory from start to finish.",
  ui_story_31870401_77_dialog_content = "I think it's safe to say you didn't lose it in Twin Pavilions Bay.",
  ui_story_31870401_78_dialog_content = "I see. I had no idea your psychic powers let you see things so clearly.",
  ui_story_31870401_79_dialog_content = "Now then, please turn to the next page and help me search again.",
  ui_story_31870401_80_dialog_content = "No problem. The next page is about... <color=#FFB400>\"The past and present life of Lepidoz\"?!</color>",
  ui_story_31870401_81_option_content = "Force Boost!",
  ui_story_31870401_82_dialog_content = "<color=#e8d9bb>Rediesel Desert</color>",
  ui_story_31870401_83_dialog_content = "Don't you ever take a break?!",
  ui_story_31870401_84_dialog_content = "We need food and rest too!",
  ui_story_31870401_85_dialog_content = "Show some manners, you two! I've been feeding you plenty of fruit this entire trip!",
  ui_story_31870401_86_dialog_content = "Now that we have such juicy gossip on Yuebai, we need to maximize its value as soon as possible.",
  ui_story_31870401_87_dialog_content = "I've always been fascinated by the Colossi of this land.",
  ui_story_31870401_88_dialog_content = "Soroz—",
  ui_story_31870401_89_dialog_content = "Lepidoz—",
  ui_story_31870401_90_dialog_content = "And the merchant ship would be—",
  ui_story_31870401_91_dialog_content = "Shadowz!",
  ui_story_31870401_92_dialog_content = "Merchant ship? What merchant ship?",
  ui_story_31870401_93_dialog_content = "Ah yes, and sometimes the answers we seek come walking right up to us!",
  ui_story_31870401_94_dialog_content = "Huh? I don't have a clue what you're going on about, but are you here to join Rediesel Wrench?",
  ui_story_31870401_95_dialog_content = "No, I just have the utmost respect and admiration for the leader of Rediesel Wrench, which is why I've come here to report some new information.",
  ui_story_31870401_96_dialog_content = "You talk funny, you know that? Besides, what's so special about Sinsa?",
  ui_story_31870401_97_dialog_content = "(Uh-oh, it appears I'm flattering the wrong person...)",
  ui_story_31870401_98_dialog_content = "(I'll just have to adjust my approach based on what he said!)",
  ui_story_31870401_99_dialog_content = "You know, seeing how big and powerful you appear to be, I'm sure your leader trusts you with many of his secrets, yes?",
  ui_story_31870401_100_dialog_content = "You got a good eye, bro! I happen to be the strongest guy in the entire Rediesel Wrench!",
  ui_story_31870401_101_dialog_content = "But, uh... What kind of secrets are you talking about?",
  ui_story_31870401_102_dialog_content = "I currently have an incredible piece of gossip related to the captain of a Lin Family merchant ship. Would you be interested in trading details of Lepidoz's existence for that?",
  ui_story_31870401_103_dialog_content = "Lepidoz, huh? Sinsa just kinda found it and then modified the heck out of it.",
  ui_story_31870401_104_dialog_content = "It's not really a secret, considering people here love repurposing old junk like that.",
  ui_story_31870401_105_dialog_content = "As for where we found Lepidoz, I don't mind telling you either: almost everything we scavenge comes straight from <color=#FFB400>the trash</color>! Long live the Rediesel Wrench!",
  ui_story_31870401_106_dialog_content = "Trash?",
  ui_story_31870401_107_dialog_content = "That's right! Whether it's a big ol' Colossus on the side of the road or a busted-up car... It's all fair game here!",
  ui_story_31870401_108_dialog_content = "After all, freedom is what we're all about!",
  ui_story_31870401_109_dialog_content = "That reminds me... What merchant ship were you talking about? Is it one of the ships docked at the mainland port?",
  ui_story_31870401_110_dialog_content = "This isn't good!",
  ui_story_31870401_111_dialog_content = "Run, run!",
  ui_story_31870401_112_dialog_content = "Hahaha! Sorry, but I must be going now! Until next time, bro!",
  ui_story_31870401_113_dialog_content = "At the time, it came as quite a shock for me too.",
  ui_story_31870401_114_dialog_content = "(So Sinsa was the one who modified Lepidoz...)",
  ui_story_31870401_115_dialog_content = "(Argh, focus! I'm supposed to be looking for Jabber!)",
  ui_story_31870401_116_dialog_content = "Jabber was present in this memory the entire time too.",
  ui_story_31870401_117_dialog_content = "Its yelling sounded just as awkward as yours.",
  ui_story_31870401_118_dialog_content = "I'm surprised your psychic powers allow you to sense your target's feelings as well...",
  ui_story_31870401_119_dialog_content = "I know what you're gonna say. Flip to the next page, right?",
  ui_story_31870401_120_dialog_content = "Yes, please! You're a fortune-teller in your own right, you know?",
  ui_story_31870401_121_dialog_content = "Alright, now for the last page—<color=#FFB400>\"Princess Zhuohua's birthday big reveal\"?!</color>",
  ui_story_31870401_122_option_content = "Force Boost!",
  ui_story_31870401_123_dialog_content = "It seems the rumors surrounding Yuebai have more or less subsided now.",
  ui_story_31870401_124_dialog_content = "Even though I've shed my blood, sweat, and tears for this task, I can't help but feel a bit bored by it.",
  ui_story_31870401_125_dialog_content = "Brag about it, why don'tcha?!",
  ui_story_31870401_126_dialog_content = "Wow, so humble!",
  ui_story_31870401_127_dialog_content = "Ugh, all your incessant squawking really makes it hard to calm down.",
  ui_story_31870401_128_dialog_content = "... Hmm? Wait, I think I hear something other than your obnoxious voices—",
  ui_story_31870401_129_dialog_content = "I hear the reason the captain won't do business with Umbraton is because that place is just like the hell described in myths.",
  ui_story_31870401_130_dialog_content = "Not only that, they say the Shadowlord looks like he has bull horns and a horse's face, and that he keeps a black dog and a white dog at his side...",
  ui_story_31870401_131_dialog_content = "... And just where did you hear those things?",
  ui_story_31870401_132_dialog_content = "More boogeyman tales, eh? It seems these people are merely speculating about Umbraton, just as before.",
  ui_story_31870401_133_dialog_content = "If I don't go to hell, then who else will go?",
  ui_story_31870401_134_dialog_content = "<color=#e8d9bb>Umbraton</color>",
  ui_story_31870401_135_dialog_content = "A normal street!",
  ui_story_31870401_136_dialog_content = "A normal shop!",
  ui_story_31870401_137_dialog_content = "It seems tales of this \"hell\" have been greatly exaggerated.",
  ui_story_31870401_138_dialog_content = "... Oh? Is that a familiar face I see?",
  ui_story_31870401_139_dialog_content = "Your Highness, this stall appears to sell items used for Astra's method of divination.",
  ui_story_31870401_140_dialog_content = "These cards... I believe they're called tarot cards? Interesting.",
  ui_story_31870401_141_dialog_content = "Jiu, I want to give it a try, to read my fortune with them.",
  ui_story_31870401_142_dialog_content = "But Your Highness...",
  ui_story_31870401_143_dialog_content = "Let's pick the one besides my hand for the first card.",
  ui_story_31870401_144_dialog_content = "Could you please explain the meaning of this card?",
  ui_story_31870401_145_dialog_content = "Oh... That's the Tower in the upright position. Not a good sign, my friend.",
  ui_story_31870401_146_dialog_content = "Your Highness, I'm sure this is just a plaything used to pass the time, so please don't...",
  ui_story_31870401_147_dialog_content = "Please don't place any faith in it at all.",
  ui_story_31870401_148_dialog_content = "I see the streets of Umbraton aren't safe from swindlers either.",
  ui_story_31870401_149_dialog_content = "But we're both fortune tellers, Princess Zhuohua. Why bring my skills into question and not this gentleman's?",
  ui_story_31870401_150_dialog_content = "I've never been one to believe in fortune-tellers or their baseless predictions. I told you as much on the ship, or have you forgotten?",
  ui_story_31870401_151_dialog_content = "Tangerines grow in the south are tangerines!",
  ui_story_31870401_152_dialog_content = "But they'd become bitter oranges in the north!",
  ui_story_31870401_153_dialog_content = "Princess Zhuohua, it would be my honor to read your fortune, if you're willing? I'm certain the divination method from our homeland will produce a much different prediction.",
  ui_story_31870401_154_dialog_content = "All I require is your birthday, and nothing more.",
  ui_story_31870401_155_dialog_content = "...",
  ui_story_31870401_156_dialog_content = "Very well then, I'm curious to see what kind of half-baked prediction you will give me.",
  ui_story_31870401_157_dialog_content = "The fourth day of the fourth month... Quite the special numbers for your date of birth, I must say.",
  ui_story_31870401_158_dialog_content = "Behold the sticks, take hold of destiny. With yin and yang combined, all things are given form...",
  ui_story_31870401_159_dialog_content = "Oh my. This is the first time I've ever seen such an incredibly bizarre destiny.",
  ui_story_31870401_160_dialog_content = "Spare us the theatrics and just tell me my fortune.",
  ui_story_31870401_161_dialog_content = "Yang Snake and Yin Tiger is a fortune also known as \"snake's head and tiger's tail,\" where the snake represents light and the tiger represents darkness.",
  ui_story_31870401_162_dialog_content = "As absurd as it may seem, this fortune actually contains a profound meaning.",
  ui_story_31870401_163_dialog_content = "From what I can see, your destiny is one of many struggles, but at the end of your journey lies a fork in the road, and beyond that lies <color=#FFB400>good fortune</color>.",
  ui_story_31870401_164_dialog_content = "What?!",
  ui_story_31870401_165_dialog_content = "But when I was a child, the fortune-teller told me that I was destined for bad luck...",
  ui_story_31870401_166_dialog_content = "Destiny and luck are two very different things. Destiny is decided by the heavens, while luck can be changed by our own hands.",
  ui_story_31870401_167_dialog_content = "Should you decide to stay on your current course, life will change for the better. Things won't be nearly as bad as they once were, I'm certain.",
  ui_story_31870401_168_dialog_content = "As for when that will happen, I cannot say. Certain things must remain secret after all.",
  ui_story_31870401_169_dialog_content = "However, this is merely my own prediction. You're free to believe in any of the predictions given to you, or none at all.",
  ui_story_31870401_170_dialog_content = "Now then, I must be going. Till next we meet, Your Highness.",
  ui_story_31870401_171_dialog_content = "Farewell!",
  ui_story_31870401_172_dialog_content = "Till next time!",
  ui_story_31870401_173_dialog_content = "...",
  ui_story_31870401_174_dialog_content = "Your Highness... What are you thinking?",
  ui_story_31870401_175_dialog_content = "... It's nothing. Come Jiu, we should return to the ship now.",
  ui_story_31870401_176_dialog_content = "Ah, it seems Princess Zhuohua's destiny is far from ordinary. The heavens have placed a great responsibility on her shoulders.",
  ui_story_31870401_177_dialog_content = "(So that's the kind of fortune Dantang was given at her birth...)",
  ui_story_31870401_178_dialog_content = "(Oh, not again! Gotta find Jabber!)",
  ui_story_31870401_179_dialog_content = "No clues on this page either, so I guess I'll have to try the next one...",
  ui_story_31870401_180_dialog_content = "Stop! Don't turn that page!",
  ui_story_31870401_181_dialog_content = "Eh?",
  ui_story_31870401_182_dialog_content = "I strongly suggest that you read no further, PlayerName. As I've said before, certain things must be kept secret.",
  ui_story_31870401_183_dialog_content = "Fine, be all mysterious then...",
  ui_story_31870401_184_dialog_content = "Please forgive me, especially when I should be thanking you for using your psychic powers to help me.",
  ui_story_31870401_185_dialog_content = "I think I know where to find Jabber now.",
  ui_story_31870401_186_dialog_content = "What? You do?!",
  ui_story_31870401_187_dialog_content = "But I didn't manage to figure anything out...",
  ui_story_31870401_188_dialog_content = "As much as I'd like to see you off, I must search for Jabber right away. I'll be sure to thank you properly at a later date.",
  ui_story_31870401_189_dialog_content = "Don't worry about it. It's not like I really did anything...",
  ui_story_31870401_190_dialog_content = "Bye for now! See you next time!",
  ui_story_31870401_191_dialog_content = "I-I'll just be going then!",
  ui_story_31870401_192_dialog_content = "<color=#e8d9bb>Some time later</color>",
  ui_story_31870401_193_dialog_content = "...",
  ui_story_31870401_194_dialog_content = "Alright, you two can both come out now.",
  ui_story_31870401_195_dialog_content = "A single plank makes no boat!",
  ui_story_31870401_196_dialog_content = "A single actor makes no play!",
  ui_story_31870401_197_dialog_content = "We did a great job together!",
  ui_story_31870401_198_dialog_content = "And we get to eat fruit all day!",
  ui_story_31870401_199_dialog_content = "Yes, yes, and I'm also willing to overlook Squawk's blunder, even though it almost ruined everything.",
  ui_story_31870401_200_dialog_content = "Here's the special supply fruit as promised. Now, stop interfering with my work!",
  ui_story_31870401_201_dialog_content = "Time to eat! Time to eat!",
  ui_story_31870401_202_dialog_content = "(Phew, inviting PlayerName proved to be quite fruitful as well!)",
  ui_story_31870401_203_dialog_content = "(Looks like I have another entry to add to the \"Scroll of Divine Ascension\" now.)",
  ui_story_31870401_204_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_31870401_205_dialog_content = "\"Experiencing and observing the Psychic abilities of the Caelestite.\"",
  ui_story_31870601_1_dialog_content = "Hey, Navigator. Doing some fishing, I see?",
  ui_story_31870601_2_dialog_content = "Yep.",
  ui_story_31870601_3_dialog_content = "What a leisurely way to pass the time!",
  ui_story_31870601_4_dialog_content = "Keeping busy in your spare time will spare you work in your busy time, so how about a divination?",
  ui_story_31870601_5_dialog_content = "Let's see... what about whether or not you'll catch a fish today?",
  ui_story_31870601_6_dialog_content = "Ahem... All become one, and death brings peace to all. The mysteries of existence cannot escape my gaze...",
  ui_story_31870601_7_dialog_content = "The Serpent Becomes A Dragon! Now that's an auspicious fortune!",
  ui_story_31870601_8_dialog_content = "Today, you'll surely catch a huge—",
  ui_story_31870601_9_dialog_content = "H-Huge what...?",
  ui_story_31870601_10_dialog_content = "A huge ribbonfish!",
  ui_story_31870601_11_dialog_content = "... Hey, wait a second! How am I supposed to catch an ocean fish when I'm fishing in a lake?!",
  ui_story_31870601_12_dialog_content = "Oh, what difference does it make where you fish? The waters of the natural world are all connected, are they not?",
  ui_story_31870601_13_dialog_content = "They say it can rain cats and dogs as well, so why can't it rain ribbonfish?",
  ui_story_31870601_14_dialog_content = "You shouldn't pay so much attention to where the fish comes from. After all, I've never made a clearer water divination in my life!",
  ui_story_31870601_15_dialog_content = "If you deny it, you won't catch so much as a scale. But if you accept it, I'm positive you'll catch an enormous fish!",
  ui_story_31870601_16_dialog_content = "I promise you won't be disappointed!",
  ui_story_31870601_17_dialog_content = "You sound really confident this time...",
  ui_story_31870601_18_dialog_content = "Do you really know that much about fishing?",
  ui_story_31870601_19_dialog_content = "Not just fishing, my friend. Nothing can hide from my eyes, not even underwater!",
  ui_story_31870601_20_dialog_content = "I may not be able to travel freely under the sea like the immortals of our legends, but I have been to the Dragon Palace and seen the world from there.",
  ui_story_31870601_21_dialog_content = "... Now you're starting to make even less sense.",
  ui_story_31870601_22_dialog_content = "Sigh, it appears that unless I tell you about my fateful experience in the Dragon Palace...",
  ui_story_31870601_23_dialog_content = "You won't be able to catch that ribbonfish.",
  ui_story_31870601_24_dialog_content = "You see, it all started when an angry debt collector chased me into the sea one day...",
  ui_story_31870601_25_dialog_content = "<color=#e8d9bb>Plop—</color>",
  ui_story_31870601_26_dialog_content = "Phew... It seems I've finally managed to lose them.",
  ui_story_31870601_27_dialog_content = "Honestly, it's their fault for not taking my divination seriously. If they had just listened, they wouldn't have lost so much money and come after me like that.",
  ui_story_31870601_28_dialog_content = "Such is life, I suppose...",
  ui_story_31870601_29_dialog_content = "Now, where exactly am I? Such a chilly, hazy place...",
  ui_story_31870601_30_dialog_content = "Hmm? Wait, am I underwater? B-But I don't know how to swim...!",
  ui_story_31870601_31_dialog_content = "By all means, I should be drowning right now, so why am I still perfectly fine?",
  ui_story_31870601_32_dialog_content = "Unless... am I already dead?!",
  ui_story_31870601_33_dialog_content = "But I didn't even get to finish reading my comics...",
  ui_story_31870601_34_dialog_content = "Pardon me, my esteemed guest, but are you alright?",
  ui_story_31870601_35_dialog_content = "Esteemed... guest?",
  ui_story_31870601_36_dialog_content = "Why, yes. You're here because the Dragon King summoned you, are you not?",
  ui_story_31870601_37_dialog_content = "I... Well then, it seems destiny meant for me to fall in the water today.",
  ui_story_31870601_38_dialog_content = "Yes, that's me. At least, it appears to be me. In fact, if nothing else, I'm mostly positive that it's me.",
  ui_story_31870601_39_dialog_content = "Very good, sir. Could you please follow us into the palace now?",
  ui_story_31870601_40_dialog_content = "The Dragon King sent us to receive you.",
  ui_story_31870601_41_dialog_content = "Very well then. Lead the way!",
  ui_story_31870601_42_dialog_content = "So, this is the Dragon Palace? It certainly seems to be!",
  ui_story_31870601_43_dialog_content = "You seem better informed than most of our guests, sir. This palace happens to be the greatest one in these waters.",
  ui_story_31870601_44_dialog_content = "Now then, would you please change your attire?",
  ui_story_31870601_45_dialog_content = "C-Change my attire? Is this customary as well?",
  ui_story_31870601_46_dialog_content = "It's important for guests to feel at home wherever they find themselves.",
  ui_story_31870601_47_dialog_content = "As such, changing clothes shouldn't be necessary... Wouldn't you agree?",
  ui_story_31870601_48_dialog_content = "Not at all, sir. If you were to attend the Dragon King's banquet while wearing such poor-looking garments...",
  ui_story_31870601_49_dialog_content = "I'm afraid you would only bring shame to the palace.",
  ui_story_31870601_50_dialog_content = "The Dragon King would blame the two of us if that were to happen.",
  ui_story_31870601_51_dialog_content = "Not to mention, His Majesty ate too many clams recently, so he already has a terrible temper.",
  ui_story_31870601_52_dialog_content = "Very well then, I'll change clothes.",
  ui_story_31870601_53_dialog_content = "Right this way, sir...",
  ui_story_31870601_54_dialog_content = "Hmm, not bad at all! These clothes are quite comfortable, though I daresay they could've used a bit more material in some places.",
  ui_story_31870601_55_dialog_content = "Though it doesn't hurt to be a little more revealing, especially when paired with such nice jewelry.",
  ui_story_31870601_56_dialog_content = "I'm pleased to hear that you like it. His Majesty has ordered us to present these clothes to you as a gift.",
  ui_story_31870601_57_dialog_content = "How very magnanimous! I'd expect nothing less from the Dragon King!",
  ui_story_31870601_58_dialog_content = "There's still some time before the banquet begins, so please wait here for now.",
  ui_story_31870601_59_dialog_content = "Until then, please partake in the sea grapes, sea apples, and sea anemone that we have prepared for you... Enjoy.",
  ui_story_31870601_60_dialog_content = "Hahaha, how wonderfully generous of you. Don't mind if I do.",
  ui_story_31870601_61_dialog_content = "Mmm! Oh, this is delicious!",
  ui_story_31870601_62_dialog_content = "I'm pleased to hear that. If you require anything else, please don't hesitate to call us.",
  ui_story_31870601_63_dialog_content = "Oh, don't mind me! I'll be fine right here.",
  ui_story_31870601_64_dialog_content = "Every cloud has a silver lining, I suppose. The ancients haven't lied to me yet!",
  ui_story_31870601_65_dialog_content = "Falling into the sea and receiving such wonderful treatment, all in the course of a single day. Quite the unexpected turn of events indeed!",
  ui_story_31870601_66_dialog_content = "There's one more matter we wish to discuss with you, sir.",
  ui_story_31870601_67_dialog_content = "By all means! I'd be more than happy to help with anything you need.",
  ui_story_31870601_68_dialog_content = "This tome records the names of all who visit our palace. Now that you have arrived, would you please sign your name on it?",
  ui_story_31870601_69_dialog_content = "But of course! All I need is a brush...",
  ui_story_31870601_70_dialog_content = "Li... Tian... Xian... There!",
  ui_story_31870601_71_dialog_content = "Thank you for providing your signature, sir... Hmm?",
  ui_story_31870601_72_dialog_content = "Wait, this isn't the name of the guest we were expecting!",
  ui_story_31870601_73_dialog_content = "Huh?",
  ui_story_31870601_74_dialog_content = "You're not the honored guest we were sent to welcome at all!",
  ui_story_31870601_75_dialog_content = "Ahem... C-Could it be that the palace recorded my name incorrectly?",
  ui_story_31870601_76_dialog_content = "We've been waiting on him hand and foot all day long, only to find out he's an imposter!",
  ui_story_31870601_77_dialog_content = "Get him, brothers!",
  ui_story_31870601_78_dialog_content = "W-Wait! Let's not be too hasty! I'm sure this is all just a misunderstanding...",
  ui_story_31870601_79_dialog_content = "Show no mercy, brothers!",
  ui_story_31870601_80_dialog_content = "N-No, please! A true gentleman deals in words, not violence...",
  ui_story_31870601_81_dialog_content = "Don't stop until he's dead...",
  ui_story_31870601_82_dialog_content = "Perhaps we'll only understand one another after a healthy exchange of blows...",
  ui_story_31870601_83_dialog_content = "How dare you make fools of us!",
  ui_story_31870601_84_dialog_content = "Today's friends can be tomorrow's allies, so it's best to...",
  ui_story_31870601_85_dialog_content = "<color=#e8d9bb>Wham! Bam! Whack!</color>",
  ui_story_31870601_86_dialog_content = "Hey look, someone's lying here! Is he still alive?",
  ui_story_31870601_87_dialog_content = "What a shame, dying so young...",
  ui_story_31870601_88_dialog_content = "Urgh... Cough... Hah...",
  ui_story_31870601_89_dialog_content = "Oh? Guess he's alive after all.",
  ui_story_31870601_90_dialog_content = "Wh-What happened?",
  ui_story_31870601_91_dialog_content = "You shouldn't play in the water if you don't know how to swim, young man.",
  ui_story_31870601_92_dialog_content = "... Was I dreaming just now?",
  ui_story_31870601_93_dialog_content = "And that's how it all happened. Well? Do you believe me now?",
  ui_story_31870601_94_dialog_content = "... Even if your story was real, that doesn't mean your divination is right.",
  ui_story_31870601_95_dialog_content = "Of course it does! You should really have more faith in me, you know.",
  ui_story_31870601_96_dialog_content = "Oh... It looks like you have a bite! Reel it in carefully!",
  ui_story_31870601_97_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_31870601_98_dialog_content = "It's...",
  ui_story_31870601_99_dialog_content = "It's really a ribbonfish!",
  ui_story_31870601_100_option_content = "Amazing! How did you make it happen?",
  ui_story_31870601_101_dialog_content = "The secrets of the universe must remain secret, lest our world fall into chaos.",
  ui_story_31870601_102_option_content = "No way! You definitely set this up!",
  ui_story_31870601_103_dialog_content = "Now you've gone too far. It's one thing to doubt my divinations, but to accuse me of trickery when I'm right is unacceptable!",
  ui_story_31870601_104_dialog_content = "Fine...",
  ui_story_31870601_105_dialog_content = "Thank you for your patronage! Now that our business is settled, I'll be on my way!",
  ui_story_31870601_106_dialog_content = "... How in the world did he do that?",
  ui_story_31870601_107_dialog_content = "Ahhh! There you are, Pavarotti! I've been looking everywhere for you!",
  ui_story_31870601_108_dialog_content = "Wait, is this your fish?",
  ui_story_31870601_109_dialog_content = "Of course! Pavarotti is my most precious pet.",
  ui_story_31870601_110_dialog_content = "I thought I'd never see it again after it accidentally fell into the lake...",
  ui_story_31870601_111_dialog_content = "Thank you for finding it, kind stranger! I doubt it would've lived much longer without your help!",
  ui_story_31870601_112_dialog_content = "D-Don't mention it..."
}
return config
